        public static readonly M04NarrativeLine[] Brief={
            new("brief-01",NarrativeSpeakerId.Laila,"Captain Laila Nasser. My helicopter is ready at the eastern landing area. Bring the four specialists to me in the APC; I can keep this extraction window open for ten minutes.","من سروان لیلا ناصرم. بالگردم توی محل فرود شرقی آماده‌ست. چهار متخصص رو با نفربر به من برسونید. ده دقیقه می‌تونم منتظر بمونم."),
            new("brief-02",NarrativeSpeakerId.Samira,"Two medics and two engineers are stranded by the western road. They are the people who can reopen the clinics and restore the network. Bring every one of them home.","دو امدادگر و دو مهندس کنار جادهٔ غربی گیر افتادن. برای راه‌انداختن درمانگاه‌ها و شبکه بهشون نیاز داریم. همه رو سالم برگردونید."),
            new("brief-03",NarrativeSpeakerId.Dalia,"Rifles cover the road; the APC carries the team. Unload beside Laila, board the helicopter, hold the area clear for twenty seconds, then fly to the marked departure zone.","تفنگدارها جاده رو پوشش بدن؛ نفربر تیم رو جابه‌جا کنه. کنار لیلا پیاده‌شون کنید و سوار بالگردش کنید. بیست ثانیه محل رو امن نگه دارید، بعد به محدودهٔ خروج پرواز کنید.")};
        public static readonly M04NarrativeLine[] Comms={new("comms-01",NarrativeSpeakerId.Laila,"All four are aboard. The landing area is clear and departure is authorized. Fly to the marked exit; I will take the team from there.","هر چهار نفر سوار شدن. محل فرود امنه و اجازهٔ خروج داریم. به محل خروج مشخص‌شده پرواز کنید؛ از اونجا تیم رو می‌برم.")};
        public static readonly M04NarrativeLine[] Debrief={
            new("debrief-01",NarrativeSpeakerId.Laila,"Four passengers accounted for. Your escort gave us the time we needed. I am joining this operation; you will have an airlift pilot when the next team needs a way out.","هر چهار نفر سالم رسیدن. پوششتون بهمون وقت داد. من هم به تیمتون ملحق می‌شم؛ برای نجات بعدی روی بالگردم حساب کنید."),
            new("debrief-02",NarrativeSpeakerId.Samira,"The engineers brought their repair records. Several outages lead back to the same fortified communications node. We finally have a place to investigate.","مهندس‌ها گزارش‌های تعمیر رو آوردن. چند تا از قطعی‌ها به یه مرکز ارتباطی حفاظت‌شده می‌رسه. بالاخره می‌دونیم کجا رو باید بررسی کنیم."),
            new("debrief-03",NarrativeSpeakerId.Aria,"Extraction confirmed. Captain Nasser is on the roster. Next objective: assess that communications node. First, let the medical team get back to work.","نجات تأیید شد. سروان ناصر هم به تیم پیوست. بعدش باید اون مرکز ارتباطی رو بررسی کنیم. فعلاً بذاریم تیم پزشکی به کارش برسه.")};
        public static readonly (string Title,string PersianTitle,string Body,string PersianBody,string Example,string PersianExample,string Mistake,string PersianMistake)[] Lessons={
            ("A rescue, in two stages","نجات در دو مرحله","Rescue all four specialists: APC first, helicopter second. You have ten minutes. Enemy kills are optional; keep the escort alive for a bonus star.","باید هر چهار متخصص رو نجات بدی: اول با نفربر، بعد با بالگرد. ده دقیقه وقت داری. لازم نیست همهٔ دشمن‌ها رو بکشی؛ اگه محافظ‌ها سالم بمونن، یه ستارهٔ اضافه می‌گیری.","Read the route, then continue.","مسیر رو بخون و ادامه بده.","Do not leave a specialist behind.","هیچ متخصصی رو جا نذار."),
            ("Select the APC","نفربر رو انتخاب کن","Select the wheeled APC beside your rifles. Keep its four seats free for the specialists. Show Me locates the APC.","نفربر چرخ‌دار کنار تفنگدارها رو انتخاب کن. چهار صندلیش رو برای متخصص‌ها خالی نگه دار. اگه پیداش نکردی، «نشان بده» رو بزن.","Select the APC before giving its movement order.","قبل از فرمان حرکت، نفربر رو انتخاب کن.","A selected rifle squad is not the transport.","گروه تفنگدار انتخاب‌شده نفربر نیست."),
            ("Reach the stranded team","به تیم گرفتار برسید","Press Move, then tap beside the four specialists on the western road. Show Me locates them. Send the rifles forward to cover the pickup.","«حرکت» رو بزن و نفربر رو کنار چهار متخصص توی جادهٔ غربی ببر. «نشان بده» جاشون رو نشونت می‌ده. تفنگدارها رو هم برای پوشش جلو بفرست.","The road gives a clear approach for the APC.","جاده مسیر مناسبی برای نزدیک‌شدن نفربر است.","Do not drive through buildings or leave the APC in enemy fire.","از میان ساختمان‌ها عبور نکن و نفربر رو زیر آتش رها نکن."),
            ("Select the specialists","متخصصان رو انتخاب کن","Select all four specialists beside the road. Keep armed escorts outside the selection. This step completes when all four are selected.","هر چهار متخصص کنار جاده رو با دکمهٔ انتخاب متخصصان انتخاب کن. محافظ‌های مسلح نباید توی این گروه باشن. وقتی هر چهار نفر انتخاب بشن، می‌ریم مرحلهٔ بعد.","Tap Select all specialists in ARIA.","دکمهٔ انتخاب همهٔ متخصصان رو در پنل آریا بزن.","Keep armed escorts out of this selection.","محافظان مسلح رو وارد این انتخاب نکن."),
            ("Board all four into the APC","هر چهار نفر رو سوار نفربر کن","Press Board, then tap the APC. Wait until its passenger list shows all four specialists before moving.","«سوارشدن» رو بزن، بعد نفربر رو انتخاب کن. قبل از حرکت، صبر کن تا هر چهار متخصص توی فهرست مسافرها باشن.","Check the passenger count before moving.","قبل از حرکت تعداد مسافران رو بررسی کن.","Moving too soon can leave a passenger walking behind.","زود راه نیفت؛ ممکنه یکی از مسافرها جا بمونه."),
            ("Escort the APC to Laila","نفربر رو تا لیلا همراهی کن","Move the loaded APC east to the marked landing area. Show Me locates Laila. Keep the rifles covering the approaching patrol.","نفربر پر رو به محل فرود مشخص‌شده توی شرق ببر. «نشان بده» جای لیلا رو نشونت می‌ده. تفنگدارها رو برای پوشش مسیر گشت دشمن نگه دار.","Keep the passenger count at four during the trip.","در طول مسیر تعداد مسافران رو روی چهار نگه دار.","Do not leave the escort behind the convoy.","محافظ‌ها رو پشت کاروان جا نذار."),
            ("Unload beside the helicopter","متخصص‌ها رو کنار بالگرد پیاده کن","Open the APC passenger panel, then tap Unload. Wait until all four specialists stand beside the helicopter. Move into open ground if unloading is blocked.","بخش مسافرهای نفربر رو باز کن و «پیاده‌شدن» رو بزن. صبر کن هر چهار متخصص کنار بالگرد پیاده بشن. اگه جا بسته‌ست، نفربر رو یه کم ببر توی فضای باز.","Unload close to the helicopter while the rifles cover.","زیر پوشش تفنگدارها، متخصص‌ها رو کنار بالگرد پیاده کن.","A rejected unload leaves passengers safely aboard; it does not transfer them.","اگه دستور پیاده‌شدن رد بشه، مسافرها توی نفربر می‌مونن و منتقل نمی‌شن."),
            ("Inspect the helicopter","بالگرد رو بررسی کن","Select Laila’s helicopter. Keep it landed beside the specialists until all four have boarded.","بالگرد لیلا رو انتخاب کن. کنار متخصص‌ها روی زمین نگهش دار تا هر چهار نفر بتونن سوار بشن.","Keep it at the landing area until all four are aboard.","تا سوارشدن هر چهار نفر اون رو در محل فرود نگه دار.","An airborne helicopter cannot instantly collect a passenger.","بالگرد باید روی زمین باشه تا مسافرها سوار بشن."),
            ("Transfer the specialists","متخصصان رو منتقل کن","Select all four specialists, press Board, then tap the landed helicopter. Check that its passenger list shows four people.","با دکمهٔ انتخاب متخصصان، هر چهار نفر رو انتخاب کن. «سوارشدن» رو بزن، بعد بالگرد روی زمین رو انتخاب کن. باید هر چهار نفر توی فهرست مسافرها باشن.","Board the team, not the escort rifle squads.","فقط تیم متخصص‌ها رو سوار کن؛ تفنگدارهای محافظ بیرون بمونن.","Flying straight to the team skips the required APC leg and will not complete the mission.","پرواز مستقیم به سمت تیم، مرحلهٔ نفربر رو حذف می‌کنه و مأموریت رو کامل نمی‌کنه."),
            ("Hold the landing area clear","محل فرود رو امن نگه دار","Keep the loaded helicopter inside the marked landing area for twenty clear seconds. Use the rifles to stop threats entering the ring. Leaving or enemy entry resets the count.","بالگرد پر رو بیست ثانیه توی حلقهٔ امن فرود نگه دار. با تفنگدارها نذار دشمن وارد حلقه بشه. اگه بالگرد بیرون بره یا دشمن وارد بشه، زمان از اول شروع می‌شه.","Wait for Laila's departure clearance.","منتظر اجازهٔ خروج لیلا بمون.","Taking off early does not award extraction progress.","اگه زود بلند شی، مرحلهٔ امن‌کردن محل فرود کامل نمی‌شه."),
            ("Fly to the departure zone","به محدودهٔ خروج پرواز کن","Select the helicopter, press Move, then tap the marked exit. Show Me locates the exit. Keep all four specialists aboard until extraction is confirmed.","بالگرد رو انتخاب کن، «حرکت» رو بزن و به محل خروج مشخص‌شده بفرستش. «نشان بده» خروج رو نشونت می‌ده. تا نجات تأیید نشده، هر چهار متخصص باید سوار بمونن.","Cross the departure area with the helicopter airborne.","با بالگرد در حال پرواز وارد محدودهٔ خروج شو.","The APC reaching the exit does not count as an airlift.","رسیدن نفربر به خروج کافی نیست؛ تیم باید با بالگرد خارج بشه."),
            ("Review your rescue","نجات رو مرور کن","Extraction is being confirmed. Keep the passengers aboard and protect the helicopter until the result appears.","دارم نجات رو تأیید می‌کنم. تا نتیجه بیاد، مسافرها رو سوار نگه دار و از بالگرد محافظت کن.","Laila joins the campaign after the first successful extraction.","بعد از اولین نجات موفق، لیلا به تیمت اضافه می‌شه.","Failure never grants rescue rewards or shows a successful departure.","شکست پاداش نجات نمی‌دهد و خروج موفق نشان نمی‌دهد.")};
        public static readonly (string Key,string English,string Persian)[] Ui={
            ("mission.m04.tutorial.hold.wait","All four specialists are aboard. Wait {0} more seconds; no click is needed. Keep the helicopter inside the yellow landing ring. The next lesson will guide you to the exit.","هر چهار متخصص سوارن. {0} ثانیهٔ دیگه صبر کن؛ لازم نیست دکمه‌ای بزنی. بالگرد رو توی حلقهٔ زرد فرود نگه دار. درس بعدی مسیر خروج رو نشونت می‌ده."),
